from lib import *
S = SS('g40')
steps = [
    step("存活堆 200 MiB,4 个 goroutine 持续分配垃圾,各跑 3 秒。A 不设限制(GOGC=100):总内存峰值 609 MB、GC 56 轮、吞吐 109.6 M 次分配/秒、GC 占 CPU 28.5%、堆目标 562 MB。B GOMEMLIMIT=300MiB:峰值 299 MB(守住了 300 MiB = 314 MB 以内)、GC 119 轮、吞吐 44.7 M/s、GC 占 51.9%;C 同样的限制加 GOGC=off:峰值 299 MB、121 轮、45.5 M/s、53.4%——限制本身就能驱动 GC。D GOMEMLIMIT=240MiB(只比存活堆多一点)GOGC=off:峰值 245 MB、152 轮、吞吐 11.2 M/s、GC 占 65.2%。E GOMEMLIMIT=150MiB(低于存活堆)GOGC=100:峰值 273 MB、129 轮、吞吐 19.9 M/s、GC 占 57.6%,SetMemoryLimit(-1) 读到当前限制 157286400。", t=tl(S(1)), done=lidx(S(1), 'A 不设限制', 'B GOMEMLIMIT=300MiB', 'C GOMEMLIMIT=300MiB'), mark=lidx(S(1), 'D GOMEMLIMIT=240MiB', 'E GOMEMLIMIT=150MiB'), b=bars([['A 无限制:吞吐(M/s)', 109.6, '109.6'], ['B 300MiB', 44.7, '44.7'], ['D 240MiB', 11.2, '11.2'], ['E 150MiB(低于存活堆)', 19.9, '19.9']], 109.6, done=[0, 1], mark=[2, 3]), kv=KV([['A 无限制', '峰值 609 MB;GC 占 28.5%;109.6 M/s'], ['B / C 300MiB', '峰值 299 MB;GC 占 52%–53%;约 45 M/s'], ['D 240MiB', '峰值 245 MB;GC 占 65.2%;11.2 M/s'], ['E 150MiB(低于存活堆)', '峰值 273 MB(超过限制);GC 占 57.6%;19.9 M/s']], ['B / C 300MiB'])),
    step("GOMEMLIMIT 的写法与默认值:不设置时 SetMemoryLimit(-1) 读到 9223372036854775807(math.MaxInt64,没有限制);512MiB → 536870912,1GiB → 1073741824,纯数字 123456789 → 123456789(单位字节),off → 9223372036854775807;1.5GiB 与 100MB 直接让程序启动失败:fatal error: malformed GOMEMLIMIT; see `go doc runtime/debug.SetMemoryLimit`(只支持 B、KiB、MiB、GiB、TiB 与整数)。", t=tl(S(2)), done=lidx(S(2), '512MiB', '1GiB', '123456789', 'off'), mark=lidx(S(2), '1.5GiB', '100MB', '不设置'), kv=KV([['不设置 / off', 'math.MaxInt64(无限制)'], ['512MiB / 1GiB / 123456789', '按 IEC 单位或字节解析'], ['1.5GiB、100MB', 'fatal error: malformed GOMEMLIMIT']], ['1.5GiB、100MB'])),
    step("限制是软的:对照 A(不设限制)与 E(限制 150MiB,低于 200 MiB 的存活堆):E 没有被杀,总内存峰值 273 MB 超过了 157 MB 的限制,吞吐从 109.6 M/s 降到 19.9 M/s,GC 轮数从 56 涨到 129,GC 占 CPU 从 28.5% 涨到 57.6%。metrics 里 /gc/limiter/last-enabled 读到 0,所以我没法确认这次是不是触发了“GC CPU 限流”。", t=tl(S(3)), done=lidx(S(3), 'A 不设限制'), mark=lidx(S(3), 'E GOMEMLIMIT=150MiB'), b=bars([['A GC 占 CPU(%)', 28.5, '28.5'], ['E GC 占 CPU', 57.6, '57.6'], ['A GC 轮数', 56, '56'], ['E GC 轮数', 129, '129']], 129, done=[0, 2], mark=[1, 3]), kv=KV([['E 的内存', '峰值 273 MB > 限制 157 MB,没有被杀'], ['E 的吞吐', '19.9 M/s(A 是 109.6 M/s)'], ['GC 的负担', 'GC 占 CPU 57.6%,129 轮']], ['E 的内存'])),
]
A = mkartg('g40', 40, 'Go,GC,GOMEMLIMIT,软内存上限,真实验证,动画演示',
    '在 Go 1.27.1 里实测 GOMEMLIMIT:存活堆 200 MiB 时不设限制峰值 609 MB、吞吐 109.6 M/s,限制 300 MiB 时峰值 299 MB、吞吐 44.7 M/s、GC 占 52% CPU(GOGC 开不开都一样);限制只比存活堆多一点时吞吐降到 11.2 M/s;限制低于存活堆时进程没被杀、内存仍超限(273 MB)、GC 占 57.6%;GOMEMLIMIT 只认整数与 B/KiB/MiB/GiB/TiB。',
    'GOGC 只看存活堆的倍数,不知道你的容器还剩多少内存。GOMEMLIMIT 给运行时一个软上限:接近上限时 GC 会更频繁,甚至在 GOGC=off 时也生效。这篇用同一个分配负载在五种设置下对比内存、GC 次数与吞吐,并验证它为什么是“软”的。',
    [('299 MB', 'GOMEMLIMIT=300MiB 时总内存的峰值(不设限制时是 609 MB)'), ('109.6 → 44.7 M/s', '用限制换来的内存上界,代价是吞吐下降'), ('273 MB', '限制 150MiB(低于存活堆)时的峰值——软上限不会杀进程,也不保证不超')],
    [('限制怎么起作用', '<p>文档(<code>go doc runtime/debug.SetMemoryLimit</code>)说限制针对 <code>MemStats.Sys - HeapReleased</code>(即 <code>/memory/classes/total</code> 减去 <code>/memory/classes/heap/released</code>),不包括二进制本身与 C 分配的内存。实验里限制 300MiB 把峰值压在 299 MB,GC 比不设限制多出一倍(119 轮对 56 轮),GC 的 CPU 占比从 28.5% 升到约 52%,吞吐掉到 41%。<code>GOGC=off</code> 加限制得到几乎相同的结果,说明限制自己就能驱动 GC。</p>'),
     ('写法与默认值', '<p>默认没有限制(<code>math.MaxInt64</code>)。<code>GOMEMLIMIT</code> 只接受整数加可选的 <code>B</code>、<code>KiB</code>、<code>MiB</code>、<code>GiB</code>、<code>TiB</code> 后缀,<code>1.5GiB</code> 或 <code>100MB</code> 会让程序启动失败。要用小数就换成更小的单位(<code>1536MiB</code>)。<code>debug.SetMemoryLimit(-1)</code> 可以读当前值。</p>'),
     ('“软”的含义', '<p>限制低于存活堆时,程序不会被杀,也不保证内存不超:实验里 273 MB 超过了 157 MB 的限制,吞吐降到 18%,GC 轮数翻倍。文档的说法是这时 GC 可能“almost continuously”运行但应用仍能前进。实验里 <code>/gc/limiter/last-enabled</code> 读到 0,GC 占 CPU 57.6%,我没有观察到 GC 的 CPU 被限制在某个上限的证据(运行时是否有这样的限流,这次没有验证)。实践上的结论:限制应当设在存活堆之上留足余量的位置,而不是接近或低于它。</p>')],
    steps,
    [ENV_G + '。存活堆是 N 个 56 字节节点组成的图(runtime.GC() 之后约 200 MiB);4 个 goroutine 不停地 new 小对象并丢弃;总内存用 /memory/classes/total:bytes 每 3 ms 取样的峰值,GC CPU 占比来自 /cpu/classes/gc/total:cpu-seconds 与 /cpu/classes/total:cpu-seconds 的差值;maxrss 来自 getrusage;每种设置只跑一次',
     '没有验证:GC 限流器是否触发(指标读到 0)、cgroup 容器里用 GOMEMLIMIT 的推荐比例(只是常见做法)、归还内存给操作系统(scavenger)的行为、amd64 上的数字、与 GOGC 同时设置的更复杂组合、多次重复运行的离散度'],
    'GOMEMLIMIT')
